window.BOOK={"key":"awam","app":"mutoon-awam","lsk":"mutoon_awam_v1","prefix":"aw_","title":"عقيدة العوام","sub":"عقيدة العوام · العقيدة · أحمد المرزوقي المالكي (ت نحو ١٢٦٢هـ) · ٥٧ بيتًا","poems":[{"id":"awam","title":"عقيدة العوام","nazim":"أحمد بن محمد بن رمضان المرزوقي المالكي المكي","death":"ت نحو ١٢٦٢هـ","meter":"الرجز","source":"ويكيبيديا العربية: عقيدة العوام (نص المنظومة، مضبوط أكثره)","srcUrl":"https://ar.wikipedia.org/wiki/عقيدة_العوام","note":"لم توجد نسخة رقمية مشكولة شكلًا تامًّا: اللفظ من نص المنظومة في ويكيبيديا العربية (٥٧ بيتًا، مضبوط الأواخر غالبًا)، مقابَلًا كلمةً كلمةً بسكربت بمتن الشاملة الذهبية (كتاب أونلاين 7189، غير مشكول)، وأكمل الذكاء الاصطناعي الشكل على ضبط المصدر والوزن، وكل شطر موزون على الرجز إلا شطرًا واحدًا (٣٢ب). يحسن مراجعته على طبعة مشكولة.","verses":[["أَبْدَأُ بِاسْمِ اللَّهِ وَالرَّحْمَنِ","وَبِالرَّحِيمِ دَائِمِ الْإِحْسَانِ"],["فَالْحَمْدُ لِلَّهِ الْقَدِيمِ الْأَوَّلِ","الْآخِرِ الْبَاقِي بِلَا تَحَوُّلِ"],["ثُمَّ الصَّلَاةُ وَالسَّلَامُ سَرْمَدَا","عَلَى النَّبِيِّ خَيْرِ مَنْ قَدْ وَحَّدَا"],["وَآلِهِ وَصَحْبِهِ وَمَنْ تَبِعْ","سَبِيلَ دِينِ الْحَقِّ غَيْرَ مُبْتَدِعْ"],["وَبَعْدُ فَاعْلَمْ بِوُجُوبِ الْمَعْرِفَهْ","مِنْ وَاجِبٍ لِلَّهِ عِشْرِينَ صِفَهْ"],["فَاللَّهُ مَوْجُودٌ قَدِيمٌ بَاقِي","مُخَالِفٌ لِلْخَلْقِ بِالْإِطْلَاقِ"],["وَقَائِمٌ غَنِي وَوَاحِدٌ وَحَيْ","قَادِرْ مُرِيدٌ عَالِمٌ بِكُلِّ شَيْ"],["سَمِيعٌ الْبَصِيرُ وَالْمُتْكَلِّمُ","لَهُ صِفَاتٌ سَبْعَةٌ تَنْتَظِمُ"],["فَقُدْرَةٌ إِرَادَةٌ سَمْعٌ بَصَرْ","حَيَاةٌ الْعِلْمُ كَلَامٌ اسْتَمَرْ"],["وَجَائِزٌ بِفَضْلِهِ وَعَدْلِهِ","تَرْكٌ لِكُلِّ مُمْكِنٍ كَفِعْلِهِ"],["أَرْسَلَ أَنْبِيَا ذَوِي فَطَانَهْ","بِالصِّدْقِ وَالتَّبْلِيغِ وَالْأَمَانَهْ"],["وَجَائِزٌ فِي حَقِّهِمْ مِنْ عَرَضِ","بِغَيْرِ نَقْصٍ كَخَفِيفِ الْمَرَضِ"],["عِصْمَتُهُمْ كَسَائِرِ الْمَلَائِكَهْ","وَاجِبَةٌ وَفَاضَلُوا الْمَلَائِكَهْ"],["وَالْمُسْتَحِيلُ ضِدُّ كُلِّ وَاجِبِ","فَاحْفَظْ لِخَمْسِينَ بِحُكْمٍ وَاجِبِ"],["تَفْصِيلُ خَمْسَةٍ وَعِشْرِينَ لَزِمْ","كُلَّ مُكَلَّفٍ فَحَقِّقْ وَاغْتَنِمْ"],["هُمْ آدَمٌ إِدْرِيسُ نُوحٌ هُودُ مَعْ","صَالِحْ وَإِبْرَاهِيمُ كُلٌّ مُتَّبَعْ"],["لُوطٌ وَإِسْمَاعِيلُ إِسْحَاقُ كَذَا","يَعْقُوبُ يُوسُفُ وَأَيُّوبُ احْتَذَى"],["شُعَيْبُ هَارُونُ وَمُوسَى وَالْيَسَعْ","ذُو الْكِفْلِ دَاوُدُ سُلَيْمَانُ اتَّبَعْ"],["إِلْيَاسُ يُونُسْ زَكَرِيَّا يَحْيَى","عِيسَى وَطَهَ خَاتِمٌ دَعْ غَيَّا"],["عَلَيْهِمُ الصَّلَاةُ وَالسَّلَامُ","وَآلِهِمْ مَا دَامَتِ الْأَيَّامُ"],["وَالْمَلَكُ الَّذِي بِلَا أَبٍ وَأُمْ","لَا أَكْلَ لَا شُرْبَ وَلَا نَوْمَ لَهُمْ"],["تَفْصِيلُ عَشْرٍ مِنْهُمُ جِبْرِيلُ","مِيكَالُ إِسْرَافِيلُ عِزْرَائِيلُ"],["مُنْكَرْ نَكِيرٌ وَرَقِيبٌ وَكَذَا","عَتِيدُ مَالِكٌ وَرِضْوَانُ احْتَذَى"],["أَرْبَعَةٌ مِنْ كُتُبٍ تَفْصِيلُهَا","تَوْرَاةُ مُوسَى بِالْهُدَى تَنْزِيلُهَا"],["زَبُورُ دَاوُدَ وَإِنْجِيلُ عَلَى","عِيسَى وَفُرْقَانٌ عَلَى خَيْرِ الْمَلَا"],["وَصُحُفُ الْخَلِيلِ وَالْكَلِيمِ","فِيهَا كَلَامُ الْحَكَمِ الْعَلِيمِ"],["وَكُلُّ مَا أَتَى بِهِ الرَّسُولُ","فَحَقُّهُ التَّسْلِيمُ وَالْقَبُولُ"],["إِيمَانُنَا بِيَوْمِ آخِرٍ وَجَبْ","وَكُلِّ مَا كَانَ بِهِ مِنَ الْعَجَبْ"],["خَاتِمَةٌ فِي ذِكْرِ بَاقِي الْوَاجِبِ","مِمَّا عَلَى مُكَلَّفٍ مِنْ وَاجِبِ"],["نَبِيُّنَا مُحَمَّدٌ قَدْ أُرْسِلَا","لِلْعَالَمِينَ رَحْمَةً وَفُضِّلَا"],["أَبُوهُ عَبْدُ اللَّهِ عَبْدُ الْمُطَّلِبْ","وَهَاشِمٌ عَبْدُ مَنَافٍ يَنْتَسِبْ"],["وَأُمُّهُ آمِنَةُ الزُّهْرِيَّهْ","أَرْضَعَتْهُ حَلِيمَةُ السَّعْدِيَّهْ"],["مَوْلِدُهُ بِمَكَّةَ الْأَمِينَهْ","وَفَاتُهُ بِطَيْبَةَ الْمَدِينَهْ"],["أَتَمَّ قَبْلَ الْوَحْيِ أَرْبَعِينَا","وَعُمْرُهُ قَدْ جَاوَزَ السِّتِّينَا"],["وَسَبْعَةٌ أَوْلَادُهُ فَمِنْهُمُ","ثَلَاثَةٌ مِنَ الذُّكُورِ تُفْهَمُ"],["قَاسِمْ وَعَبْدُ اللَّهِ وَهْوَ الطَّيِّبُ","وَطَاهِرٌ بِذَيْنِ ذَا يُلَقَّبُ"],["أَتَاهُ إِبْرَاهِيمُ مِنْ سُرِّيَّهْ","فَأُمُّهُ مَارِيَةُ الْقِبْطِيَّهْ"],["وَغَيْرُ إِبْرَاهِيمَ مِنْ خَدِيجَهْ","هُمْ سِتَّةٌ فَخُذْ بِهِمْ وَلِيجَهْ"],["وَأَرْبَعٌ مِنَ الْإِنَاثِ تُذْكَرُ","رِضْوَانُ رَبِّي لِلْجَمِيعِ يُذْكَرُ"],["فَاطِمَةُ الزَّهْرَاءُ بَعْلُهَا عَلِي","وَابْنَاهُمَا السِّبْطَانِ فَضْلُهُمْ جَلِي"],["فَزَيْنَبٌ وَبَعْدَهَا رُقَيَّهْ","وَأُمُّ كُلْثُومٍ زَكَتْ رَضِيَّهْ"],["عَنْ تِسْعِ نِسْوَةٍ وَفَاةُ الْمُصْطَفَى","خُيِّرْنَ فَاخْتَرْنَ النَّبِيَّ الْمُقْتَفَى"],["عَائِشَةٌ وَحَفْصَةٌ وَسَوْدَهْ","صَفِيَّةٌ مَيْمُونَةٌ وَرَمْلَهْ"],["هِنْدٌ وَزَيْنَبٌ كَذَا جُوَيْرِيَهْ","لِلْمُؤْمِنِينَ أُمَّهَاتٌ مَرْضِيَهْ"],["حَمْزَةُ عَمُّهُ وَعَبَّاسٌ كَذَا","عَمَّتُهُ صَفِيَّةٌ ذَاتُ احْتِذَا"],["وَقَبْلَ هِجْرَةِ النَّبِيِّ الْإِسْرَا","مِنْ مَكَّةٍ لَيْلًا لِقُدْسٍ يُدْرَى"],["وَبَعْدَ إِسْرَاءٍ عُرُوجٌ لِلسَّمَا","حَتَّى رَأَى النَّبِيُّ رَبًّا كَلَّمَا"],["مِنْ غَيْرِ كَيْفٍ وَانْحِصَارٍ وَافْتَرَضْ","عَلَيْهِ خَمْسًا بَعْدَ خَمْسِينَ فَرَضْ"],["وَبَلَّغَ الْأُمَّةَ بِالْإِسْرَاءِ","وَفَرْضِ خَمْسَةٍ بِلَا امْتِرَاءِ"],["قَدْ فَازَ صِدِّيقٌ بِتَصْدِيقٍ لَهُ","وَبِالْعُرُوجِ الصِّدْقُ وَافَى أَهْلَهُ"],["وَهَذِهِ عَقِيدَةٌ مُخْتَصَرَهْ","وَلِلْعَوَامِ سَهْلَةٌ مُيَسَّرَهْ"],["نَاظِمُ تِلْكَ أَحْمَدُ الْمَرْزُوقِي","مَنْ يَنْتَمِي لِلصَّادِقِ الْمَصْدُوقِ"],["وَالْحَمْدُ لِلَّهِ وَصَلَّى سَلَّمَا","عَلَى النَّبِيِّ خَيْرِ مَنْ قَدْ عَلَّمَا"],["وَالْآلِ وَالصَّحْبِ وَكُلِّ مُرْشِدِ","وَكُلِّ مَنْ بِخَيْرِ هَدْيٍ يَقْتَدِي"],["وَأَسْأَلُ الْكَرِيمَ إِخْلَاصَ الْعَمَلْ","وَنَفْعَ كُلِّ مَنْ بِهَا قَدِ اشْتَغَلْ"],["أَبْيَاتُهَا مَيْزٌ بِعَدِّ الْجُمَّلِ","تَارِيخُهَا لِي حَيُّ غُرٍّ جُمَّلِ"],["سَمَّيْتُهَا عَقِيدَةَ الْعَوَامِ","مِنْ وَاجِبٍ فِي الدِّينِ بِالتَّمَامِ"]],"secs":{"1":"عقيدة العوام"}}],"sharh":false};
